window.BOOK={"key":"shabrawi","app":"mutoon-shabrawi","lsk":"mutoon_shabrawi_v1","prefix":"sh_","title":"منظومة الشبراوي","sub":"منظومة الشبراوي في النحو · النحو · عبد الله بن محمد الشبراوي (ت ١١٧١هـ) · ٥١ بيتًا","poems":[{"id":"shabrawi","title":"منظومة الشبراوي","nazim":"عبد الله بن محمد بن عامر الشبراوي","death":"ت ١١٧١هـ","meter":"البسيط","source":"كتاب أونلاين (الشاملة الذهبية): منظومة الشبراوي في النحو وزيادتها للحكمي","srcUrl":"https://ketabonline.com/ar/books/103087","note":"النص المشكول من نشرة «منظومة الشبراوي في النحو وزيادتها للحكمي» بعد إخراج زيادات الحكمي (المميَّزة فيها بقوسين)، فبقي الأصل ٥١ بيتًا. النشرة لا تكتب السكون فأُثبت آليًّا، وكل شطر موزون على البسيط. لم يوجد مصدر رقمي ثانٍ للمقابلة؛ وأول المنظومة فيها «يا طالب العلم» فأُثبت المشهور «يا طالب النحو».","verses":[["يَا طَالِبَ النَّحْوِ خُذْ مِنِّي قَوَاعِدَهُ","مَنْظُومَةً جُمْلَةً مِنْ أَحْسَنِ الْجُمَلِ"],["فِي ضِمْنِ خَمْسِينَ بَيْتًا لَا تَزِيدُ سِوَى","بَيْتٍ بِهِ قَدْ سَأَلْتُ الْعَفْوَ عَنْ زَلَلِي"],["إِنْ أَنْتَ أَتْقَنْتَهَا هَانَتْ مَسَائِلُهُ","عَلَيْكَ مِنْ غَيْرِ تَطْوِيلٍ وَلَا مَلَلِ"],["أَمَّا الْكَلَامُ اصْطِلَاحًا فَهْوَ عِنْدَهُمُ","مُرَكَّبٌ فِيهِ إِسْنَادٌ كَقَامَ عَلِي"],["وَالِاسْمُ وَالْفِعْلُ ثُمَّ الْحَرْفُ جُمْلَتُهَا","أَجْزَاؤُهُ فَهْوَ عَنْهَا غَيْرُ مُنْتَقِلِ"],["فَالِاسْمُ يُعْرَفُ بِالتَّنْوِينِ ثُمَّ بِأَلْ","وَالْجَرِّ أَوْ بِحُرُوفِ الْجَرِّ كَالرَّجُلِ"],["وَالْفِعْلُ بِالسِّينِ أَوْ قَدْ أَوْ بِسَوْفَ وَإِنْ","أَرَدْتَ حَرْفًا فَمِنْ تِلْكَ الْأُمُورِ خَلِي"],["وَحَدُّ الِاعْرَابِ تَغْيِيرُ الْأَوَاخِرِ مِنْ","اسْمٍ وَفِعْلٍ أَتَى مِنْ بَعْدِ ذِي عَمَلِ"],["فَالرَّفْعُ وَالنَّصْبُ فِي غَيْرِ الْحُرُوفِ وَمَا","يَخْتَصُّ بِالْجَرِّ إِلَّا الِاسْمُ فَامْتَثِلِ"],["وَالْجَزْمُ لِلْفِعْلِ فَالْأَنْوَاعُ أَرْبَعَةٌ","وَلَيْسَ لِلْحَرْفِ إِعْرَابٌ فَلَا تُطِلِ"],["وَقَدْ تَبَيَّنَ أَنَّ الِاسْمَ لَيْسَ لَهُ","جَزْمٌ وَلَيْسَ لِفِعْلٍ جَرُّ مُتَّصِلِ"],["لِكُلِّ نَوْعٍ عَلَامَاتٌ مُفَصَّلَةٌ","فَالرَّفْعُ أَرْبَعَةٌ فِي قَوْلِ كُلِّ وَلِي"],["وَالنَّصْبُ خَمْسُ عَلَامَاتٍ وَثَالِثُهَا","خَفْضٌ ثَلَاثٌ وَلِلْجَزْمِ اثْنَتَانِ تَلِي"],["وَالرَّفْعُ أَبْوَابُهُ سَبْعٌ سَتَسْمَعُهَا","تُتْلَى عَلَيْكَ بِوَصْفٍ لِلْعُقُولِ جَلِي"],["الْفَاعِلُ اسْمٌ لِفِعْلٍ قَدْ تَقَدَّمَهُ","كَجَاءَ زَيْدٌ فَقَصِّرْ يَا أَخَا الْعَذَلِ"],["وَنَائِبُ الْفَاعِلِ اسْمٌ كَانَ مُنْتَصِبًا","فَصَارَ مُرْتَفِعًا لِلْحَذْفِ فِي الْأُوَلِ"],["كَنِيلَ خَيْرٌ وَصِيمَ الشَّهْرُ أَجْمَعُهُ","وَقِيلَ قَوْلٌ وَزَيْدٌ بِالْوُشَاةِ بُلِي"],["وَالْمُبْتَدَا نَحْوُ زَيْدٌ قَائِمٌ وَأَنَا","فِي الدَّارِ وَهْوَ أَبُوهُ غَيْرُ مُمْتَثِلِ"],["وَمَا بِهِ تَمَّ مَعْنَى الْمُبْتَدَا خَبَرٌ","كَالشَّأْنِ فِي نَحْوِ زَيْدٌ صَاحِبُ الدُّوَلِ"],["وَكَانَ تَرْفَعُ مَا قَدْ كَانَ مُبْتَدَأً","إِسْمًا وَتَنْصِبُ مَا قَدْ كَانَ بَعْدُ وَلِي"],["وَمِثْلُهَا أَدَوَاتٌ أُلْحِقَتْ عَمَلًا","كَبَاتَ أَصْبَحَ ذُو الْأَمْوَالِ فِي الْحُلَلِ"],["أَمْسَى وَأَضْحَى وَظَلَّ الْعَبْدُ مُبْتَسِمًا","وَصَارَ لَيْسَ كِرَامُ النَّاسِ كَالسَّفَلِ"],["وَأَرْبَعٌ مِثْلُهَا وَالنَّفْيُ يَلْزَمُهَا","أَوْ شِبْهُهُ كَالْفَتَى فِي الدَّارِ لَمْ يَزَلِ"],["وَلَيْسَ يَبْرَحُ أَوْ يَنْفَكُّ مُجْتَهِدًا","تَاللَّهِ تَفْتَأُ مِنْ ذِكْرَاهُ فِي شُغُلِ"],["وَإِنَّ تَفْعَلُ هَذَا الْفِعْلَ مُنْعَكِسًا","كَإِنَّ قَوْمَكَ مَعْرُوفُونَ بِالْجَدَلِ"],["لَعَلَّ لَيْتَ كَأَنَّ الرَّكْبَ مُرْتَحِلٌ","لَكِنَّ زَيْدَ ابْنَ عَمْرٍو غَيْرُ مُرْتَحِلِ"],["وَخُذْ بَقِيَّةَ أَبْوَابِ النَّوَاسِخِ إِذْ","كَانَتْ ثَلَاثًا وَذَاكَ الثُّلْثُ لَمْ يُقَلِ"],["فَظَنَّ تَنْصِبُ جُزْأَيْ جُمْلَةٍ نُسِخَا","بِهَا وَضُمَّ لَهَا أَمْثَالَهَا وَسَلِ"],["مِثَالُهُ ظَنَّ زَيْدٌ خَالِدًا ثِقَةً","وَقَدْ رَأَى النَّاسُ عَمْرًا وَاسِعَ الْأَمَلِ"],["وَتِلْكَ سِتَّةُ أَبْوَابٍ سَأُتْبِعُهَا","بِالنَّعْتِ وَالْعَطْفِ وَالتَّوْكِيدِ وَالْبَدَلِ"],["كَزَيْدٌ الْعَدْلُ قَدْ وَافَى وَخَادِمُهُ","أَبُو الضِّيَا نَفْسُهُ مِنْ غَيْرِ مَا مَهَلِ"],["وَبَعْدَ ذِكْرِي لِمَرْفُوعَاتِ الِاسْمِ عَلَى","تَرْتِيبِهَا السَّابِقِ الْخَالِي مِنَ الْخَلَلِ"],["أَقُولُ جُمْلَةُ مَنْصُوبَاتِهِ عَدَدًا","سَبْعٌ وَعَشْرٌ وَهَذَا أَوْضَحُ السُّبُلِ"],["مِنْهَا الْمَفَاعِيلُ خَمْسٌ مُطْلَقٌ وَبِهِ","وَفِيهِ مَعْهُ لَهُ وَانْظُرْ إِلَى الْمُثُلِ"],["ضَرَبْتُ ضَرْبًا أَبَا عَمْرٍو غَدَاةَ أَتَى","وَجِئْتُ وَالنِّيلَ خَوْفًا مِنْ عِتَابِكَ لِي"],["وَلَا كَإِنَّ لَهَا اسْمٌ بَعْدَهُ خَبَرٌ","فَإِنْ يَكُنْ مُفْرَدًا فَافْتَحْهُ ثُمَّ صِلِ"],["وَانْصِبْ مُضَافًا بِهَا أَوْ مَا يُشَابِهُهُ","كَلَا أَسِيرَ هَوًى يَنْجُو مِنَ الْخَطَلِ"],["وَابْنِ الْمُنَادَى عَلَى مَا كَانَ مُرْتَفِعًا","بِهِ وَقُلْ يَا إِمَامُ اعْدِلْ وَلَا تَمِلِ"],["وَإِنْ تُنَادِ مُضَافًا أَوْ مُشَاكِلَهُ","قُلْ يَا رَحِيمًا بِنَا يَا غَافِرَ الزَّلَلِ"],["وَالْحَالُ نَحْوُ أَتَاكَ الْعَبْدُ مُعْتَذِرًا","يَرْجُو رِضَاكَ وَمِنْهُ الْقَلْبُ فِي وَجَلِ"],["وَإِنْ تُمَيِّزْ فَقُلْ عِشْرُونَ جَارِيَةً","عِنْدَ الْأَمِيرِ وَقِنْطَارٌ مِنَ الْعَسَلِ"],["وَانْصِبْ بِإِلَّا إِذَا اسْتَثْنَيْتَ نَحْوُ أَتَتْ","كُلُّ الْقَبَائِلِ إِلَّا رَاكِبَ الْجَمَلِ"],["وَجُرَّ مَا بَعْدَ غَيْرٍ أَوْ خَلَا وَعَدَا","كَذَا سِوَى نَحْوُ قَامُوا غَيْرَ ذِي الْحِيَلِ"],["وَبَعْدَ نَفْيٍ وَشِبْهِ النَّفْيِ إِنْ وَقَعَتْ","إِلَّا يَجُوزُ لَكَ الْأَمْرَانِ فَامْتَثِلِ"],["وَانْصِبْ بِكَانَ وَإِنَّ اسْمًا يُكَمِّلُهَا","مَعْ تَابِعٍ مُفْرَدٍ يُغْنِيكَ عَنْ جُمَلِ"],["وَاخْتِمْ بِأَبْوَابِ مَخْفُوضَاتِ الِاسْمِ عَسَى","تَنَالُ حُسْنَ خِتَامٍ مُنْتَهَى الْأَجَلِ"],["عَوَامِلُ الْخَفْضِ عِنْدَ الْقَوْمِ جُمْلَتُهَا","ثَلَاثَةٌ إِنْ تُرِدْ تَمْثِيلَهَا فَقُلِ"],["غُلَامُ زَيْدٍ أَتَى فِي مَنْظَرٍ حَسَنٍ","فَانْظُرْهُ وَاحْذَرْ سِهَامَ الْأَعْيُنِ النُّجُلِ"],["إِسْمٌ وَحَرْفٌ بِلَا خُلْفٍ وَتَابِعُهَا","فِيهِ الْخِلَافُ نَمَا فَاسْأَلْ عَنِ الْعِلَلِ"],["وَاعْلَمْ بِأَنَّ حُرُوفَ الْجَرِّ قَدْ ذُكِرَتْ","فِي الْكُتْبِ فَارْجِعْ لَهَا وَاسْتَغْنِ عَنْ عَمَلِ"],["يَا رَبِّ عَفْوًا عَنِ الْجَانِي الْمُسِيءِ فَقَدْ","ضَاقَتْ عَلَيْهِ بِطَاحُ السَّهْلِ وَالْجَبَلِ"]],"secs":{"1":"في الكلام وما يتألف منه","8":"في الإعراب اصطلاحا","14":"في مرفوعات الأسماء","32":"في منصوبات الأسماء","46":"في مخفوضات الأسماء"}}],"sharh":false};
